@startuml

abstract class Contract {
  + getCharges() : double
  + getBalance() : double
  + setBalance(double) : void
}

class BasicContract extends Contract {
  + contractNumber : int
  + balance : double
}

class Option extends Contract {}

class DataOption extends Option {
  + getCharges() : double
}

class SmsOption extends Option {
  + getCharges() : double
}

class MinutesOption extends Option {
  + getCharges() : double
}

class DoubleTransferRateOption extends Option {
  + getCharges() : double
}

@enduml

